INSERT INTO `mod_forever_journal_lore` (`ID`, `Zone`, `Kind`, `SortOrder`, `Faction`, `Races`, `Classes`, `Era`, `Title`, `Body`, `Sources`) VALUES
(495000, 495, 0, 1, 0, 0, 0, 0, 'Howling Fjord', 'Green meadows cut by rivers that chill to the bone, pine forests, and tall rugged fjords. This was the seat of the vrykul''s power. Long ago, like many ancient races, they tried to sleep through the curse of flesh that was turning them from immortal stone into mortal people, and so slept through the Great Sundering, leaving their keeps and villages empty for thousands of years.\n\nNow the Lich King''s Scourge has gone across Northrend waking them, and they have come back to claim their homes. Many have fallen under the Frozen Throne''s sway, and they hurl themselves against the newcomers from the south until their numbers are spent.', 'warcraft.wiki.gg: Howling Fjord (History, Geography)'),
(495001, 495, 1, 1, 0, 0, 0, 0, 'Valgarde', 'The oldest Alliance settlement in Northrend, begun after the Third War by the lucky few who survived Prince Arthas'' betrayal. When the Valiance Expedition arrived it was a sleepy little nothing of a town with a decent anchorage, and the vrykul across the river were still asleep. A month later they woke, and "malformed giants appeared out of thin air", as Vice Admiral Keller puts it. Dragonflayer raiders and their worgs and proto-drakes have attacked the walls ever since.', 'warcraft.wiki.gg: Valgarde (History)'),
(495002, 495, 1, 2, 0, 0, 0, 0, 'Vengeance Landing', 'The Forsaken''s port, built and run entirely by Sylvanas Windrunner''s Hand of Vengeance, with docks for ships from Tirisfal Glades. The whole town looks sickly even from a distance, with a yellow pall hanging over the vale around it.', 'warcraft.wiki.gg: Vengeance Landing'),
(495003, 495, 1, 3, 0, 0, 0, 0, 'New Agamand', 'A new Forsaken town in their own dark, spindly gothic style, named for the Agamand family of Tirisfal. Since Sylvanas came to power, the Royal Apothecary Society has worked on a New Plague meant to wipe out the Scourge. Here they are testing it, and the land around the town has turned dead and brown. The vrykul town of Halgrind has become their testing ground.', 'warcraft.wiki.gg: New Agamand; warcraft.wiki.gg: Halgrind'),
(495004, 495, 1, 4, 0, 0, 0, 0, 'Utgarde Keep', 'The seat of King Ymiron, a massive keep of stone blocks and flying buttresses on Lake Cauldros, with giant skulls carved into the cliffs beneath it. Its height mirrors the vrykul''s social ladder: the higher one stands, the higher one lives. It and Wyrmskull Village below are home to the Dragonflayer clan, which leads the vrykul of Northrend.', 'warcraft.wiki.gg: Utgarde Keep'),
(495005, 495, 1, 5, 0, 0, 0, 0, 'Nifflevar and Baleheim', 'The vrykul towns of the fjord. Nifflevar of the Dragonflayer clings to the cliffs above Daggercap Bay, its houses built out over the drop. The Winterskorn hold Skorn and Baleheim; they prefer to throw frostbolts from their towers rather than man harpoon guns, and they have turned against the Forsaken.', 'warcraft.wiki.gg: Nifflevar; warcraft.wiki.gg: Skorn; warcraft.wiki.gg: Baleheim'),
(495006, 495, 1, 6, 0, 0, 0, 0, 'Gjalerbron', 'A vrykul fortress in the northern mountains where the vrykul, with the Scourge''s help, perform rituals to wake their sleeping kin and to raise their dead. Its Waking Halls run down level after level, full of slumbering vrykul; one can only imagine an entire race filling such a place for thousands of years.', 'warcraft.wiki.gg: Gjalerbron; warcraft.wiki.gg: Waking Halls'),
(495007, 495, 1, 7, 0, 0, 0, 0, 'Westguard Keep and Fort Wildervar', 'Westguard Keep, on the western cliffs, is the Alliance''s door into Northrend by air. Fort Wildervar, at the foot of Frostblade Peak, supplies the expeditions pushing towards the Grizzly Hills and receives human colonists coming to settle the north.', 'warcraft.wiki.gg: Westguard Keep; warcraft.wiki.gg: Fort Wildervar'),
(495008, 495, 1, 8, 0, 0, 0, 0, 'The Titan Statues', 'The Explorers'' League has found huge, almost intact statues in the cliffs of the fjord, the work of the titans, and with them a new race of iron dwarves that may hint at the dwarves'' own ancient origins. The iron dwarves have taken some of the sites and stopped the digging.', 'warcraft.wiki.gg: Baelgun''s Excavation Site; warcraft.wiki.gg: Ivald''s Ruin; warcraft.wiki.gg: Howling Fjord (Wrath of the Lich King)'),
(495009, 495, 1, 9, 0, 0, 0, 0, 'Kamagua', 'The largest tuskarr village in the fjord, its round-backed houses shaped like monstrous fish and dug down into the frozen ground to keep warm. Many wandering tuskarr clans stop here. Iskaal, to the east, is in pirate hands, and its survivors have fled to Kamagua.', 'warcraft.wiki.gg: Kamagua; warcraft.wiki.gg: Iskaal'),
(495010, 495, 1, 10, 0, 0, 0, 0, 'Shield Hill and the Kvaldir', 'An ancient vrykul burial ground at the fjord''s southern tip. The Northsea Freebooters, out of simple greed, robbed its graves and disturbed its dead. That brought the kvaldir to Northrend''s shores: cursed souls called out of the sea to raid the coasts and carry off souls to their mistress, Helya. The tuskarr tried to return what was stolen. It was too late.', 'warcraft.wiki.gg: Shield Hill; warcraft.wiki.gg: Howling Fjord (Wrath of the Lich King)'),
(495011, 495, 1, 11, 0, 0, 0, 0, 'The Ember Clutch', 'A forest that burns forever on ancient magic, where the proto-dragons mate. Since they woke, the Dragonflayers have invaded it to take the whelps.', 'warcraft.wiki.gg: Ember Clutch'),
(495012, 495, 1, 12, 0, 0, 0, 0, 'The Frozen Glade', 'A glade of frost nymphs still untouched by the Scourge. Another nearby, the Twisted Glade, has already been corrupted.', 'warcraft.wiki.gg: Frozen Glade; warcraft.wiki.gg: Twisted Glade'),
(495013, 495, 1, 13, 0, 0, 0, 0, 'Camp Winterhoof', 'A taunka village of bright totem poles and round houses built to shed snow, around hot springs that bubble up from the mountain.', 'warcraft.wiki.gg: Camp Winterhoof'),
(495050, 495, 3, 1, 0, 0, 0, 0, 'The Landing of Arthas', 'In the Third War, Prince Arthas came north with the 1st Legion to destroy the dreadlord Mal''Ganis, and Muradin Bronzebeard''s expedition joined him. When his father called them home, Arthas hired mercenaries to burn his own ships and blamed them for it, so that his men would have to stay and fight. After he took up Frostmourne and slew Mal''Ganis, he slaughtered his own followers and raised them as Scourge.', 'warcraft.wiki.gg: Howling Fjord (Third War)');
